class PreprocessingServingModule(tf.Module):
def __init__(self):
super().__init__()
self.bias = tf.Variable([1.0], dtype=tf.float32)

@tf.function(input_signature=[tf.TensorSpec(shape=[None, 1], dtype=tf.float32, name="input_tensor")])
def __call__(self, input_tensor):
# Process and calculate predictions
processed = input_tensor * 2.0
output = processed + self.bias
return {"prediction": output}

module = PreprocessingServingModule()

# Export custom defined signature to disk
tf.saved_model.save(
module,
export_dir="/tmp/serving_models/target_model/1",
signatures={"serving_default": module.__call__}

